static void p32(uint8_t*p,uint32_t v){p[0]=(uint8_t)v;p[1]=(uint8_t)(v>>8U);p[2]=(uint8_t)(v>>16U);p[3]=(uint8_t)(v>>24U);}static void p64(uint8_t*p,uint64_t v){uint32_t i;for(i=0U;i<8U;++i)p[i]=(uint8_t)(v>>(i*8U));}static uint32_t g32(const uint8_t*p){return(uint32_t)p[0]|((uint32_t)p[1]<<8U)|((uint32_t)p[2]<<16U)|((uint32_t)p[3]<<24U);}static uint64_t g64(const uint8_t*p){uint64_t v=0U;uint32_t i;for(i=0U;i<8U;++i)v|=(uint64_t)p[i]<<(i*8U);return v;}
