cadr_status cadr_m4_media_compare(const uint8_t*l,uint64_t lc,const uint8_t*r,uint64_t rc,cadr_m4_media_difference*d){cadr_m4_media_header lh,rh;cadr_m4_media_turn*lt,*rt;uint64_t ln,rn,i,limit;cadr_status s;if(d==NULL)return CADR_STATUS_INVALID_ARGUMENT;s=decode_validate(l,lc,&lh,&lt,&ln);if(s!=CADR_STATUS_OK)return s;s=decode_validate(r,rc,&rh,&rt,&rn);if(s!=CADR_STATUS_OK){free(lt);return s;}limit=lc<rc?lc:rc;for(i=0U;i<limit;++i)if(l[i]!=r[i]){d->turn_ordinal=i<64U?UINT64_MAX:(i-64U)/352U;d->byte_offset=i;d->left_byte=l[i];d->right_byte=r[i];free(lt);free(rt);return CADR_STATUS_ARTIFACT_MISMATCH;}if(lc!=rc){d->turn_ordinal=limit<64U?UINT64_MAX:(limit-64U)/352U;d->byte_offset=limit;d->left_byte=lc>limit?l[limit]:0U;d->right_byte=rc>limit?r[limit]:0U;free(lt);free(rt);return CADR_STATUS_ARTIFACT_MISMATCH;}free(lt);free(rt);(void)lh;(void)rh;(void)ln;(void)rn;return CADR_STATUS_OK;}
